\begin{definition}
A \emph{metric} on a set $X$ is a function $d:X\times X\to[0,\infty)$ satisfying, for all $x,y,z\in X$:
\begin{enumerate}
\item $d(x,y)=0$ if and only if $x=y$ (identity of indiscernibles);
\item $d(x,y)=d(y,x)$ (symmetry);
\item $d(x,z)\le d(x,y)+d(y,z)$ (triangle inequality).
\end{enumerate}
The pair $(X,d)$ is a \emph{metric space}. Nonnegativity is included in the specified codomain. Distances are finite real numbers. We allow $X$ to be empty.
\end{definition}

\section*{Examples}
\begin{example}
On $\mathbb{R}$, $d(x,y)=|x-y|$ is the usual metric. On $\mathbb{R}^n$, the Euclidean metric is
\[
d(x,y)=\left(\sum_{i=1}^{n}(x_i-y_i)^2\right)^{1/2}.
\]
\end{example}
\begin{example}
On any set $X$, put $d(x,x)=0$ and $d(x,y)=1$ whenever $x\ne y$. This is the \emph{discrete metric}. An open ball of radius $1/2$ consists of its center alone.
\end{example}
\begin{example}
If $Y\subseteq X$, restricting $d$ to $Y\times Y$ gives a metric on $Y$, called the \emph{subspace metric}.
\end{example}

\section*{The induced topology}
For $x\in X$ and $r>0$, the open ball is
\[
B_d(x,r)=\{y\in X:d(x,y)<r\}.
\]
\begin{definition}
The \emph{metric topology} consists of those subsets $U\subseteq X$ such that each $x\in U$ has some $r>0$ with $B_d(x,r)\subseteq U$.
A topological space is \emph{metrizable} if its topology is the metric topology for some metric on its underlying set. A metrizable space need not have a particular metric specified; a metric space does.
\end{definition}
\begin{proof}
The empty set satisfies the condition vacuously, and $X$ satisfies it. For a union, a point belongs to one member, whose ball also lies in the union. For the intersection of two open sets containing $x$, take the smaller of their two radii. Thus these sets form a topology. Moreover, if $y\in B_d(x,r)$, the triangle inequality gives
$B_d(y,r-d(x,y))\subseteq B_d(x,r)$.
Hence balls are open and form a basis for this topology.
\end{proof}

\begin{theorem}
Every metric space, with its metric topology, is Hausdorff.
\end{theorem}
\begin{proof}
For distinct $x,y$, set $r=d(x,y)/3>0$. If $z$ belonged to both $B_d(x,r)$ and $B_d(y,r)$, then
\[
d(x,y)\le d(x,z)+d(z,y)<2r<d(x,y),
\]
a contradiction. These balls are disjoint open neighborhoods of the two points.
\end{proof}

\section*{Further connections}
The balls $B_d(x,1/n)$, for positive integers $n$, form a countable neighborhood basis at $x$: for any radius $r>0$, choose $n$ with $1/n<r$. Thus metric spaces are first countable.
A metric space need not be second countable: an uncountable set with the discrete metric has every singleton open, so every basis must contain all singletons.
Different metrics can induce the same topology; see metric equivalence.

